package study.apps;
import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class DomainTests{static class Fake implements Store {Map<String,Poll> polls=new HashMap<>();Map<String,Map<String,String>> votes=new HashMap<>();public void ready(){}public Poll create(Poll p){if(polls.putIfAbsent(p.id(),p)!=null)throw new Problem(409,"duplicate");votes.put(p.id(),new HashMap<>());return p;}public void vote(String id,String voter,String option){Poll p=polls.get(id);if(p==null||!p.options().contains(option))throw new Problem(400,"invalid");if(votes.get(id).putIfAbsent(voter,option)!=null)throw new Problem(409,"duplicate");}public Map<String,Long> results(String id){Map<String,Long> r=new HashMap<>();for(String o:polls.get(id).options())r.put(o,votes.get(id).values().stream().filter(o::equals).count());return r;}}
 @Test void businessBoundariesAndConflicts(){Fake store=new Fake();Domain d=new Domain(store);d.create(new PollInput("poll","Question",List.of("yes","no")));d.vote("poll",new VoteInput("voter","yes"));assertEquals(1L,store.results("poll").get("yes"));assertEquals(0L,store.results("poll").get("no"));assertThrows(Problem.class,()->d.vote("poll",new VoteInput("voter","no")));assertThrows(Problem.class,()->d.vote("poll",new VoteInput("other","missing")));}
}
